data.beam_point.render:
{"ok": ["M2FS_VENV=/path/to/fnal/data/crv_fastsim/venv_eaf; M2FS_CODE=/path/to/fnal/code
[ -x "$M2FS_VENV/bin/python" ] || /cvmfs/mu2e.opensciencegrid.org/env/ana/current/bin/python -m venv --system-site-packages "$M2FS_VENV" || exit 2
"$M2FS_VENV/bin/python" -c "import jax" 2>/dev/null || "$M2FS_VENV/bin/python" -m pip install -q "jax[cuda12]==0.11.2" || exit 2
git -C "$M2FS_CODE" log -1 --format="umbrella %h" 2>/dev/null; git -C "$M2FS_CODE/crv" log -1 --format="crv %h" 2>/dev/null
A() { local c=$1; shift; [ "$c" = python ] && c="$M2FS_VENV/bin/python"; ( cd "$M2FS_CODE" && PYTHONPATH="$M2FS_CODE/core:$M2FS_CODE/crv:$M2FS_CODE/tracker" XLA_PYTHON_CLIENT_PREALLOCATE=false "$c" "$@" ); }
G4T=/path/to/fnal/data/crv_fastsim/../beam_fastsim/g4ref_full/g4ref.npz   # kit fnal_data is .../crv_fastsim
[ -r "$G4T" ] || { echo "missing $G4T"; exit 3; }
case move_extras12.txt in
  nominal) GEOM="" ;;
  /*) GEOM=move_extras12.txt ;;
  *) GEOM="$M2FS_CODE/beam/geom/"move_extras12.txt ;;
esac
[ -z "$GEOM" ] || [ -r "$GEOM" ] || { echo "missing geometry $GEOM"; exit 3; }
A python -c "import jax, sys; print(jax.devices()); sys.exit(jax.default_backend() != 'gpu')" || { echo "JAX not on the GPU"; exit 5; }
( cd "$M2FS_CODE" && PYTHONPATH="$M2FS_CODE/core:$M2FS_CODE/beam" XLA_PYTHON_CLIENT_PREALLOCATE=false \
  "$M2FS_VENV/bin/python" -m beamfastsim point --g4 "$G4T" ${GEOM:+--geom "$GEOM"} --n 105350 --seed 1 \
  --repeat 0 --batch 131072 --chunk 400 --out "$M2FS_OUT" ) > "$M2FS_OUT/point.txt" 2>&1 || { tail -20 "$M2FS_OUT/point.txt"; exit 6; }
tail -3 "$M2FS_OUT/point.txt"
", {"cores": 4, "gpu_type": "a100", "gpus": 1, "mem_gb": 24, "minutes": 30}]}

data.reco_bench.render:
{"ok": ["module load apptainer >/dev/null 2>&1
M2FS_OUT=$(readlink -f "$M2FS_OUT")   # the scratch area may be a symlink (UVA): bind the real path
A() { apptainer exec --nv --cleanenv --env CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0} -B "$M2FS_OUT" --pwd /opt/mu2e-fastsim /x/m.sif "$@"; }
echo "host $(hostname) job ${SLURM_JOB_ID:-none} out $M2FS_OUT"; nvidia-smi -L
A python -c "import jax, sys; print(jax.devices()); sys.exit(jax.default_backend() != 'gpu')" || { echo "JAX not on the GPU"; exit 5; }
A python -m crvfastsim reco-bench synthetic --stage chain --max-events 200000 --length 12 \
  --batch 65536 --repeat 3 --seed 20261021 --outdir "$M2FS_OUT/bench" > "$M2FS_OUT/bench.txt" 2>&1 || exit 6
A python - "$M2FS_OUT" <<'EOF'
import glob, json, sys
j = json.load(open(sorted(glob.glob(sys.argv[1] + "/bench/*.json"))[-1]))
def find(d, k):
    if isinstance(d, dict):
        if k in d and isinstance(d[k], (int, float)): return d[k]
        for v in d.values():
            r = find(v, k)
            if r is not None: return r
    return None
m = {k: float(find(j, k)) for k in ("events_per_s", "first_call_s", "events") if find(j, k) is not None}
json.dump(m, open(sys.argv[1] + "/metrics.json", "w"))
EOF
", {"cores": 8, "gpu_type": "a100", "gpus": 1, "mem_gb": 48, "minutes": 30}]}
